using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckSnake.Editor {
public static class SnakePresentationAuthoring {
 public static void Upgrade(){EditorSceneManager.OpenScene(SnakeAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<SnakeMatch>();Install(m);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();SnakeAuthoring.Validate(m);}
 public static void Install(SnakeMatch m){SportsMatchAudioAuthoring.Install(m,m.trucks);var cameras=m.drivingViews.rally.views.Select(v=>v.view).Concat(new[]{m.broadcast.view}).ToArray();SportsWeatherRenderingAuthoring.Install(m.gameObject,cameras,SnakeAuthoring.Folder);SportsScenicGradeAuthoring.Install(m.gameObject,cameras,SnakeAuthoring.Folder,-.35f);SportsSnowAuthoring.InstallScene();
  string[] architecture={"SM_Buildings_Commercial_01","SM_Buildings_Commercial_03","SM_Buildings_Commercial_06","SM_Buildings_Commercial_08","SM_Buildings_Hotel_01","SM_Buildings_House_01_V1","SM_Buildings_House_02_V1","SM_Buildings_House_04_V1"};int index=0;foreach(var renderer in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Include).Where(r=>r.name=="City block"||r.name=="Imported city building").ToArray()){if(renderer.transform.Find("Owned city architecture")!=null||renderer.transform.Find("Owned Snake architecture")!=null)continue;var bounds=renderer.bounds;var root=new GameObject("Owned Snake architecture").transform;root.position=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);root.SetParent(renderer.transform,true);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(root,"Assets/JC_LP_MegaCity/Prefabs/Buildings/"+architecture[index++%architecture.Length]+".prefab",bounds.size,0,true,SnakeAuthoring.Folder);renderer.enabled=false;}
  var source=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/NWH/Common/TerrainLayers/AsphaltLayer.terrainlayer");var asphalt=SportsEventAuthoring.Mat(SnakeAuthoring.Folder,"Connected world road asphalt",new Color(.68f,.7f,.72f),.1f);asphalt.mainTexture=source.diffuseTexture;asphalt.SetTexture("_BumpMap",source.normalMapTexture);asphalt.EnableKeyword("_NORMALMAP");asphalt.mainTextureScale=Vector2.one*18;
  foreach(var road in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Include)){var taxi=road.GetComponent<LWS.TruckTaxi.TruckTaxiSurface>();if(road.GetComponent<LWS.InterstateHauler.LwsRoadSurface>()!=null||taxi!=null&&taxi.isRoad)road.sharedMaterial=asphalt;}
  EditorUtility.SetDirty(m);
 }
 public static void Menu(){const string icon="Assets/TruckSnake/Art/Truck Snake Icon.png";SpriteImport(icon,1024);const string receipt="Logs/TruckSports/EssentialRelease/Snake/Native/Convoy/result.txt",capture="Logs/TruckSports/EssentialRelease/Snake/Native/Convoy/fifty-1920x1080.png",preview="Assets/TruckSports/Art/Previews/TruckSnake.png";if(!File.Exists(receipt)||!File.ReadAllText(receipt).Contains("ERRORS=0")||!File.Exists(capture))throw new InvalidOperationException("A successful real fifty-trailer capture is required before installing menu art.");File.Copy(capture,preview,true);AssetDatabase.ImportAsset(preview,ImportAssetOptions.ForceSynchronousImport);SpriteImport(preview,1024);SportsNewEntriesAuthoring.Install();}
 static void SpriteImport(string path,int size){AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.mipmapEnabled=false;importer.alphaIsTransparency=true;importer.wrapMode=TextureWrapMode.Clamp;importer.maxTextureSize=size;importer.SaveAndReimport();}
}
}
